import{_ as s,C as i,o as t,c as l,a2 as n,b as o,w as r,a as d,E as u,a3 as p}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Blue Plugin Installer","description":"Browse, install, and manage Minecraft plugins from Modrinth, CurseForge, Hangar, SpigotMC, and Polymart — a Blueprint extension for Pterodactyl Panel.","frontmatter":{"title":"Blue Plugin Installer","description":"Browse, install, and manage Minecraft plugins from Modrinth, CurseForge, Hangar, SpigotMC, and Polymart — a Blueprint extension for Pterodactyl Panel."},"headers":[],"relativePath":"blue-plugin-installer/index.md","filePath":"blue-plugin-installer/index.md","lastUpdated":null}'),g={name:"blue-plugin-installer/index.md"};function h(c,e,m,b,f,P){const a=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=n('<h1 id="blue-plugin-installer" tabindex="-1">Blue Plugin Installer <a class="header-anchor" href="#blue-plugin-installer" aria-label="Permalink to &quot;Blue Plugin Installer&quot;">​</a></h1><p><strong>Browse, install, and manage Minecraft plugins from multiple providers</strong> — a Blueprint extension for the Pterodactyl panel that lets your users discover and install plugins straight into their server&#39;s <code>/plugins</code> directory from the server dashboard.</p><p>Blue Plugin Installer adds a <strong>Plugin Installer</strong> tab to every server&#39;s sidebar. Users pick a provider — <strong>Modrinth, CurseForge, Hangar, SpigotMC, or Polymart</strong> — filter by type and Minecraft version, browse versions, and install with one click. The panel downloads the plugin file server-side and uploads it to the node through Wings.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for PingLess Studios by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/blue-plugin-installer" target="_blank" rel="noreferrer">GitHub Repo</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Studio</a></p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',6)),(t(),o(p,null,{default:r(()=>[u(a,{id:"mermaid-18",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Panel%5BPterodactyl%20Panel%5D%0A%20%20%20%20%20%20%20%20UI%5BServer%20Sidebar%20-%20Plugin%20Installer%20tab%5D%20--%3E%20API%5BClient%20API%20%2Fapi%2Fclient%2Fextensions%2Fblueplugininstaller%5D%0A%20%20%20%20%20%20%20%20ADMIN%5BAdmin%20Settings%20Page%5D%20--%3E%20STORE%5B(Extension%20Settings)%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20STORE%0A%20%20%20%20%20%20%20%20API%20--%3E%7Cdownload%7C%20TMP%5BTemp%20storage%20plugins%2F%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Providers%5BPlugin%20Providers%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20MR%5BModrinth%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20CF%5BCurseForge%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20HG%5BHangar%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20SP%5BSpigotMC%20via%20Spiget%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20PM%5BPolymart%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Node%5BWings%20Node%5D%0A%20%20%20%20%20%20%20%20TMP%20--%3E%7Cupload%20via%20NodeJWTService%7C%20WINGS%5BWings%20Daemon%5D%0A%20%20%20%20%20%20%20%20WINGS%20--%3E%20PLUGINS%5B%22server%20%2Fplugins%20directory%22%5D%0A%20%20%20%20end%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n(`<p>The <strong>panel</strong> proxies all provider traffic (your CurseForge API key stays server-side). For installs, the panel first <strong>downloads</strong> the plugin file itself, then <strong>uploads</strong> it to the server through Wings using a short-lived node JWT, and cleans up the temp copy.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Five providers</strong> — Modrinth and Hangar (keyless), SpigotMC via the Spiget API (keyless), Polymart, and CurseForge (API key set once by the admin, kept server-side).</li><li><strong>Rich search</strong> — text query, loader/type filter (Bukkit, Paper, Spigot, …), Minecraft version filter, sort modes, paginated results.</li><li><strong>Version browser</strong> — versions per plugin with names and download counts before installing.</li><li><strong>One-click install</strong> — panel downloads the file and uploads it into <code>/plugins</code> via Wings; the user sees success/failure immediately.</li><li><strong>Permission-aware</strong> — browsing requires <code>file.read</code>, installing requires <code>file.create</code> on the server.</li><li><strong>Minimal admin surface</strong> — one setting (the CurseForge API key) at <strong>Admin → Extensions → Blue Plugin Installer</strong>.</li><li><strong>Blueprint-native</strong> — installs with one <code>blueprint -install</code> command; a manual standalone path ships for panels where the CLI can&#39;t run.</li></ul><hr><h2 id="blueprint-vs-standalone" tabindex="-1">Blueprint vs Standalone <a class="header-anchor" href="#blueprint-vs-standalone" aria-label="Permalink to &quot;Blueprint vs Standalone&quot;">​</a></h2><p>Both distributions ship the <strong>same</strong> extension source. The difference is only how it lands on your panel.</p><table tabindex="0"><thead><tr><th></th><th>Blueprint (recommended)</th><th>Standalone (manual)</th></tr></thead><tbody><tr><td>Installer</td><td><code>blueprint -install blueplugininstaller-vX.Y.Z.blueprint</code></td><td>Hand-placed files per <code>standalone/INSTALLATION.md</code></td></tr><tr><td>Requirement</td><td>Blueprint CLI on the panel</td><td>Blueprint <strong>framework</strong> on the panel (no CLI)</td></tr><tr><td>Updates</td><td>Install the newer <code>.blueprint</code></td><td>Repeat the manual steps</td></tr><tr><td>Removal</td><td><code>blueprint -remove blueplugininstaller</code></td><td>Reverse the manual steps</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Standalone still needs the Blueprint framework</p><p>The controllers use <code>BlueprintAdminLibrary</code> and the React components import through Blueprint&#39;s <code>@/blueprint/extensions/*</code> alias. There is no Blueprint-free variant of this addon — the standalone path only replaces the CLI.</p></div><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueplugininstaller-v1.0.3.blueprint</span></span></code></pre></div><p>Then open <strong>Admin → Extensions → Blue Plugin Installer</strong> and set your CurseForge API key (only needed for CurseForge results).</p><p>See <a href="./getting-started/installation">Installation</a> for the full guide, and the <a href="./configuration/reference">Configuration Reference</a> for every setting.</p>`,14))])}const A=s(g,[["render",h]]);export{k as __pageData,A as default};
